import "server-only";
import { db } from "@/lib/db";
import { billingConfig } from "@/lib/billing/config";

import { getEffectivePlan } from "@/lib/entitlements";

export async function readBillingStatus(userId: string) {
  let config: ReturnType<typeof billingConfig> | null = null;
  try {
    config = billingConfig();
  } catch {
    /* unavailable until configured */
  }
  const user = await db.user.findUniqueOrThrow({
    where: { id: userId },
    select: {
      id: true,
      plan: true,
      subscriptionStatus: true,
      dodoSubscriptionId: true,
      currentPeriodStart: true,
      currentPeriodEnd: true,
      cancelAtPeriodEnd: true,
      gracePeriodEnd: true,
      billingCountry: true,
      billingCurrency: true,
      dodoCustomerId: true,
      planOverride: true,
      planOverrideStartsAt: true,
      planOverrideExpiresAt: true,
      grandfatheredUntil: true,
      deletionRequestedAt: true,
      isSuspended: true,
      gmailAuthorized: true,
    },
  });
  // Persisted evidence remains readable during provider configuration outages.
  const [subscription, attempt] = await Promise.all([
    db.billingSubscription.findFirst({
      where: { userId, dodoSubscriptionId: user.dodoSubscriptionId ?? "" },
      select: {
        settledPaymentId: true,
        cancelRequestedAt: true,
        recurringAmountMinor: true,
        currency: true,
      },
    }),
    db.checkoutAttempt.findFirst({
      where: { userId },
      orderBy: [{ createdAt: "desc" }, { id: "desc" }],
      select: { status: true },
    }),
  ]);
  const control = await db.systemControl.findUnique({
    where: { key: "global" },
    select: {
      billingCheckoutEnabled: true,
      dodoEnvironment: true,
      dodoBusinessId: true,
    },
  });
  const configured = Boolean(
    config &&
    control &&
    ((control.dodoEnvironment === null && control.dodoBusinessId === null) ||
      (control.dodoEnvironment === config.environment &&
        control.dodoBusinessId === config.businessId)),
  );
  const now = new Date();
  return {
    configured,
    checkoutEnabled: configured && Boolean(control?.billingCheckoutEnabled),
    cancellationPending: Boolean(subscription?.cancelRequestedAt),
    mode: configured
      ? config?.environment === "live_mode"
        ? ("live" as const)
        : ("test" as const)
      : null,
    plan: getEffectivePlan(user, now),
    status: user.subscriptionStatus,
    paymentConfirmed: Boolean(subscription?.settledPaymentId),
    cancelAtPeriodEnd: user.cancelAtPeriodEnd,
    periodStart: user.currentPeriodStart?.toISOString() ?? null,
    recurringAmountMinor: subscription?.recurringAmountMinor ?? null,
    recurringCurrency: subscription?.currency ?? null,
    isSuspended: user.isSuspended,
    periodEnd: user.currentPeriodEnd?.toISOString() ?? null,
    gracePeriodEnd: user.gracePeriodEnd?.toISOString() ?? null,
    billingCountry: user.billingCountry,
    billingCurrency: user.billingCurrency,
    hasCustomer: Boolean(user.dodoCustomerId),
    checkoutState: attempt?.status ?? null,
    hasOverride: Boolean(
      (user.planOverride !== null &&
        user.planOverrideStartsAt &&
        user.planOverrideStartsAt <= now &&
        (!user.planOverrideExpiresAt || user.planOverrideExpiresAt > now)) ||
      (user.grandfatheredUntil && user.grandfatheredUntil > now),
    ),
  };
}
export type ClientBillingStatus = Awaited<ReturnType<typeof readBillingStatus>>;
